# DK ALK.  Aabenraa Amtsb - Løgumkloster Amtsb
#
let ah = path("d3.dk.alk.1");
let hl = path("d3.dk.alk.2");
let fp = path("d3.dk.fpb");
let rb = path("d3.dk.rbb");

with detail = 3, railway = :third :narrow:g1000 :pax :removed {
    # point.dk.Aabenraa-Amtsb  dk.ARG

    with link = "line.dk.ALK" {
        track(ah[:aba + 0.49sw, :abn - 0.49sw]);
    }
 
    with link = "point.dk.Aabenraa-Nørreport", railway = :station {
        track(ah[:abn - 0.5sw, :abn + 0.5sw]);
        marker(:left :de.hp :casing, ah[:abn + 0.5dl] << 0.5lt);
    }

    with link = "line.dk.ALK" {
        track(ah[:abn + 0.49sw, :abn + 1.11km]);
        line_label(:left:se, ah[:abn + 1.1km] << 0.5lt, "ALK");
        track(ah[:abn + 1.09km, :kna - 0.49sw]);
    }
 
    with link = "point.dk.Knappen", railway = :station {
        track(ah[:kna - 0.5sw, :kna + 0.5sw]);
        marker(:left :de.hst, ah[:kna + 0.5dl] << 0.5lt);
        slabel(:right, ah[:kna] >> 0.5lt + (0.7dt, 0.9dt), "Knappen");
    }

    with link = "line.dk.ALK" {
        track(ah[:kna + 0.49sw, :sto - 0.49sw]);
